constraints:
1 <= x,y <= 10^{9}

expected time complexity: O(log(max(x,y)))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def shortestPath(self, a, b):
		ans = 0
		y = max(a, b)
		x = min(a, b)
		while y > x:
			y = y // 2
			ans += 1
			if x > y:
				x = x // 2
				ans += 1
		return ans
